import { apiClient } from "@/lib/apiClient";

// apiv3 tur yorumları (eski reviews tablosu). Create/update/user-list sanctum (auth-token-v3);
// public liste + oy app-token (tarayıcı proxy'si X-App-Token ekler).

export default async function saveTourReview({ data, token, tourId }: { data: any; token: string; tourId: number }) {
  return apiClient(`/b2c/tour/${tourId}/reviews`, {
    method: "POST",
    auth: "sanctum",
    token,
    body: data,
  });
}

export async function updateTourReview({ data, token }: { data: any; token: string }) {
  return apiClient(`/b2c/tour/review/update`, {
    method: "POST",
    auth: "sanctum",
    token,
    body: data,
  });
}

export async function getUserReviews({ token }: { token: string }) {
  return apiClient(`/b2c/reviews`, { auth: "sanctum", token });
}

export async function getTourReviews({ tourID }: { tourID: number }) {
  try {
    return await apiClient(`/b2c/tours/${tourID}/reviews`);
  } catch {
    // Reviews are non-critical — never crash the page on transient failures.
    return { data: [] };
  }
}

export async function voteReview({
  reviewId,
  type,
  action,
}: {
  reviewId: string | number;
  type: "vote-useful" | "vote-useless";
  action: string;
}) {
  return apiClient(`/b2c/reviews/${reviewId}/${type}/${action}`, { method: "POST" });
}
