// @ts-nocheck
import Rating from "react-rating";
import React, { useEffect, useRef, useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import formatDate from "@/helpers/FormatDate";
import { getCookie } from "cookies-next";
import Image from "next/image";
import {
  faStar,
  faThumbsUp,
  faThumbsDown,
} from "@fortawesome/free-solid-svg-icons";
import saveTourReview, {
  getTourReviews,
  updateTourReview,
  voteReview,
} from "@/services/reviewTour";
import {
  faStar as faRegularStar,
  faThumbsUp as faThumbsUpReg,
  faThumbsDown as faThumbsDownReg,
} from "@fortawesome/free-regular-svg-icons";
import Modal from "./modal";
import { inputCls, primaryBtnCls, spinnerCls } from "./ui";

/**
 * REVIEWS CREATE AND UPDATE COMPONENT
 * */
export default function Ratings({
  tourID,
  modalOnly = false,
  updatableReview = null,
  open = false,
  onClose = () => {},
}: {
  tourID: any;
  modalOnly: boolean;
  updatableReview: any;
  open?: boolean;
  onClose?: () => void;
}) {
  const [reviews, setReviews] = useState([]);
  const [rating, setRating] = useState(0);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [reviewSaved, setReviewSaved] = useState(false);
  const [submitError, setSubmitError] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [token, setToken] = useState("");
  const commentRef = useRef();

  const fetchReviews = async () => {
    getTourReviews({ tourID: tourID }).then((res) => {
      setReviews(
        (res?.data ?? []).map((review) => ({
          ...review,
          likeIcon: faThumbsUpReg,
          dislikeIcon: faThumbsDownReg,
        }))
      );
    });
  };

  useEffect(() => {
    setToken(getCookie("auth-token-v3"));
    fetchReviews();
  }, []);

  useEffect(() => {
    setRating(updatableReview?.rating);
  }, [updatableReview]);

  const updateReviewVote = (
    reviewId: string | number,
    type: "vote-useful" | "vote-useless",
    action: "like" | "unlike" | "dislike" | "undislike"
  ) => {
    //local update
    setReviews((prevReviews) =>
      prevReviews.map((r) => {
        if (r.id !== reviewId) return r; // return other reviews unchanged

        // clone review
        const updated = { ...r };

        if (type === "vote-useful") {
          const delta = action === "like" ? +1 : -1;
          updated.useful = (r.useful ?? 0) + delta;
          updated.likeIcon = action === "like" ? faThumbsUp : faThumbsUpReg;
        } else {
          const delta = action === "dislike" ? +1 : -1;
          updated.useless = (r.useless ?? 0) + delta;
          updated.dislikeIcon =
            action === "dislike" ? faThumbsDown : faThumbsDownReg;
        }

        return updated;
      })
    );

    // update server-side (apiv3 — type=vote-useful|vote-useless, action=like/unlike/dislike/undislike)
    voteReview({ reviewId, type, action });
  };

  const submitReviewHandler = async () => {
    setIsSubmitted(true);
    setTimeout(() => {
      setIsSubmitted(false);
    }, 3000);

    if (
      rating == 0 ||
      commentRef.current.value == "" ||
      commentRef.current.value.length < 10
    ) {
      return;
    }
    setIsSaving(true);

    if (!updatableReview) {
      saveTourReview({
        data: {
          rating: rating,
          comment: commentRef.current.value,
        },
        token: getCookie("auth-token-v3"),
        tourId: tourID,
      }).then((res) => {
        if (res.id) {
          setReviewSaved(true);
        } else {
          setSubmitError(true);
        }
        setIsSaving(false);
      });
    }
    if (updatableReview) {
      updateTourReview({
        data: {
          id: updatableReview.id,
          rating: rating,
          comment: commentRef.current.value,
        },
        token: getCookie("auth-token-v3"),
      }).then((res) => {
        if (res.id) {
          setReviewSaved(true);
        } else {
          setSubmitError(true);
        }
        setIsSaving(false);
      });
    }
  };

  return (
    <Modal
      open={open}
      onClose={onClose}
      staticBackdrop
      title={
        <span>
          {updatableReview ? "Review update" : "Customer review"}
          <span className="tw-block tw-text-[13px] tw-font-normal tw-text-[#5d556c]">
            We want to hear from you about this tour
          </span>
        </span>
      }
    >
      {!token && (
        <div className="tw-mb-4">
          <p className="tw-text-[18px] tw-font-semibold tw-text-[#14101c]">
            Please login to your account first.
          </p>
          <a href="/auth/login" className="tw-text-[#854ec9]">
            Click here to login
          </a>
        </div>
      )}

      {token && (
        <div className="tw-mb-4 tw-flex tw-items-center">
          <img
            src={
              getCookie("user-avatar") && getCookie("user-avatar") != "null"
                ? getCookie("user-avatar")
                : "/images/no-profile.png"
            }
            className="tw-rounded-full"
            alt="noProfile"
            height={50}
            width={50}
          />

          <div className="tw-ml-3">
            <div className="tw-text-base tw-font-semibold tw-text-[#14101c] tw-m-0">
              {getCookie("user-full-name")}
            </div>
            <span className="tw-text-[#5d556c]">
              {" "}
              Today | {formatDate(new Date())}
            </span>
          </div>
        </div>
      )}

      <div>
        <Rating
          emptySymbol={
            <FontAwesomeIcon
              icon={faRegularStar}
              className="tw-text-[#c9c4d4]"
              size={"xl"}
            />
          }
          fullSymbol={
            <FontAwesomeIcon
              icon={faStar}
              className="tw-text-[#f5a623]"
              size={"xl"}
            />
          }
          readonly={reviewSaved || !token}
          initialRating={rating}
          onClick={(value) => setRating(value)}
        />
        {isSubmitted && rating == 0 && (
          <div className="tw-text-sm tw-text-[#dc3545]"> Please select rating here</div>
        )}
      </div>

      <textarea
        ref={commentRef}
        defaultValue={updatableReview?.comment}
        className={`${inputCls} tw-mt-3`}
        readOnly={reviewSaved || !token}
        name="review"
        id="review"
        cols="30"
        rows="7"
      ></textarea>
      {isSubmitted && commentRef.current.value == "" && (
        <div className="tw-text-sm tw-text-[#dc3545]"> Please add your comment</div>
      )}
      {isSubmitted &&
        commentRef.current.value &&
        commentRef.current.value.length < 10 && (
          <div className="tw-text-sm tw-text-[#dc3545]">
            {" "}
            Comment too short. Please add more text
          </div>
        )}

      <div className="tw-text-right">
        <button
          disabled={isSaving || reviewSaved || !token}
          onClick={submitReviewHandler}
          className={`${primaryBtnCls} tw-mt-3`}
        >
          Submit Review
        </button>
      </div>

      {isSaving && (
        <div className="tw-text-center tw-py-2">
          <span
            className={`${spinnerCls} tw-text-[#854ec9] tw-h-8 tw-w-8`}
            role="status"
          ></span>
          <p className="tw-mt-3">Submitting. Please wait.</p>
        </div>
      )}

      {reviewSaved && (
        <div className="tw-my-2 tw-rounded-[10px] tw-bg-[rgba(22,163,74,0.08)] tw-px-4 tw-py-3 tw-text-[13.5px] tw-text-[#15803d]">
          Thank you very much for your review!
        </div>
      )}

      {submitError && (
        <div className="tw-my-2 tw-rounded-[10px] tw-bg-[rgba(239,68,68,0.08)] tw-px-4 tw-py-3 tw-text-[13.5px] tw-text-[#b91c1c]">
          An error occurred. Please try again later.
        </div>
      )}
    </Modal>
  );
}
